"""Emprendimiento y Empleabilidad EPJA Media N1 y N2, módulo 4: OAD-13 a OAD-16 (proyecto de vida: características personales, alternativas de ocupación, meta y plan de acción). Todo en papel; casos ficticios y cifras de ejemplo."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Todo se resuelve con lo escrito en la ficha: los casos son ficticios y las cifras son de ejemplo. No se necesita calculadora, internet ni materiales especiales. Las actividades abiertas piden reflexión personal solo si la persona quiere compartirla; siempre pueden resolverse con el caso ficticio entregado."
build = make_build(MATERIALS)

O13 = "EPJA-EMEM-NM1y2-OAD-13"
O14 = "EPJA-EMEM-NM1y2-OAD-14"
O15 = "EPJA-EMEM-NM1y2-OAD-15"
O16 = "EPJA-EMEM-NM1y2-OAD-16"
PRIOR = ["Sé que he aprendido cosas en la vida, dentro y fuera de la escuela.", "Puedo pensar en lo que quiero lograr a futuro, aunque aún no lo tenga claro."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_):
    stmt, example, crit, errors, feedback = op
    evidence = ["hoja con el trabajo escrito que muestra: " + "; ".join(crit)]
    build(oa, n, F, use=use, prior=PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=(stmt, example, crit, evidence, errors, feedback), reinforce=rf, extend=ex_)


