  [("seguimiento", "comparar lo logrado con lo esperado"), ("atraso", "diferencia entre lo esperado y lo logrado"), ("ajuste del plan", "cambio concreto que se hace tras el seguimiento"), ("autonomía", "capacidad de decidir y actuar por sí misma o por sí mismo")],
